#include <iostream>
#include <vector>
#include <string>
#include <queue>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    string tasks;
    cin >> tasks;
    long long cool;
    cin >> cool;

    vector<long long> counts(26, 0);
    for (char c : tasks) counts[c - 'A']++;
    priority_queue<long long> heap;
    for (long long c : counts) {
        if (c > 0) heap.push(c);
    }
    long long total = 0;
    while (!heap.empty()) {
        vector<long long> kept;
        long long used = 0;
        for (long long slot = 0; slot <= cool && !heap.empty(); slot++) {
            long long c = heap.top();
            heap.pop();
            used++;
            if (c > 1) kept.push_back(c - 1);
        }
        for (long long c : kept) heap.push(c);
        total += heap.empty() ? used : cool + 1;
    }
    cout << total << "\n";

    return 0;
}

