import java.io.*;
import java.util.*;

public class Main {
    static BufferedReader in = new BufferedReader(new InputStreamReader(System.in));
    static StringTokenizer tokens = new StringTokenizer("");

    static String next() throws IOException {
        while (!tokens.hasMoreTokens()) {
            tokens = new StringTokenizer(in.readLine());
        }
        return tokens.nextToken();
    }

    public static void main(String[] args) throws IOException {
        String tasks = next();
        long cool = Long.parseLong(next());

        long[] counts = new long[26];
        for (char c : tasks.toCharArray()) counts[c - 'A']++;
        PriorityQueue<Long> heap = new PriorityQueue<>(Collections.reverseOrder());
        for (long c : counts) {
            if (c > 0) heap.add(c);
        }
        long total = 0;
        while (!heap.isEmpty()) {
            List<Long> kept = new ArrayList<>();
            long used = 0;
            for (long slot = 0; slot <= cool && !heap.isEmpty(); slot++) {
                long c = heap.poll();
                used++;
                if (c > 1) kept.add(c - 1);
            }
            for (long c : kept) heap.add(c);
            total += heap.isEmpty() ? used : cool + 1;
        }
        System.out.println(total);
    }
}
